#!/usr/bin/env python3
"""Reassemble the pinned OCS slave, unchanged. Generated bytes stay in tmp/."""
import argparse
import json
import os
from pathlib import Path
import re
import struct
import subprocess
import sys

from variants import ocs as VARIANT
import capstone
from cd32_static import ROOT, crc16, require, sha
from amigaxdev.patchlist import decode

SLAVE_SHA = VARIANT.SLAVE_SHA
GAME_SHA = VARIANT.GAME_SHA
# Half-open slave hunk offsets: entry, KickEmu ROM helpers and DOS dispatch,
# generated boot stub, cache flush trampoline, game loader/options and helpers.
# Tables, strings, header and initial state are emitted as data, never decoded.
CODE = [(0, 4), (0x34, 0x62), (0x1d4, 0x43e), (0x44c, 0x4e4),
        (0x4e8, 0x624), (0x686, 0x698), (0x6a0, 0x754),
        (0x7b2, 0xe5c), (0xeb8, 0xebe), (0xee8, 0xef4),
        (0x10de, 0x11e4), (0x1210, 0x129a), (0x138e, 0x142e),
        (0x145a, 0x147c)]
SELECTORS = VARIANT.SELECTORS


def new_output(path):
    out = (ROOT / path).resolve()
    require((ROOT / 'tmp').resolve() in out.parents, 'output must be below tmp/')
    require(not out.exists(), 'output exists; nothing overwritten')
    return out


def guard_sites(game):
    """Check displaced file bytes independently of the whole-file identity guard."""
    sites = []
    for line in (ROOT / 'manifest/ocs-patch-sites.tsv').read_text().splitlines():
        if not line or line.startswith('#'):
            continue
        hunk, offset, file_offset, length, digest = line.split('\t')
        start, count = int(file_offset, 16), int(length)
        require(sha(game[start:start + count]) == digest,
                f'displaced bytes differ at OCS hunk {hunk}:{offset}')
        sites.append({'hunk': int(hunk), 'offset': offset,
                      'file_offset': file_offset, 'length': count, 'sha256': digest})
    require(len(sites) == 8, 'expected eight original English patch sites')
    return sites


def guard_game(game):
    require(sha(game) == GAME_SHA, 'unsupported/changed OCS game; English 00e8 required')
    require(crc16(game) == 0x00e8, 'English CRC mismatch')
    return guard_sites(game)


def revision_lists(code):
    """Read the actual LEA/CMP/branch selector, not a CRC-only invented policy."""
    result = {}
    for pos, crc, target in SELECTORS:
        opcode, disp, cmpop, actual_crc = struct.unpack_from('>HhHH', code, pos)
        require(opcode == 0x47fa and cmpop == 0x0c40 and actual_crc == crc,
                'revision selector instruction changed')
        require(pos + 2 + disp == target, 'revision selector target changed')
        branch = struct.unpack_from('>H', code, pos + 8)[0]
        if pos != 0x1170:
            require(branch >> 8 == 0x67 and pos + 10 + (branch & 255) == 0x117c,
                    'revision success branch changed')
        else:
            require(branch == 0x6600 and
                    pos + 10 + struct.unpack_from('>h', code, pos + 10)[0] == 0x1470,
                    'unsupported revision abort changed')
        entries = list(decode(code, target))
        require(len(entries) == 9 and entries[-1][1] == 'END', 'invalid revision list')
        require([entry[1] for entry in entries] == ['PS', 'L', 'L', 'P', 'NOP', 'W', 'S', 'B', 'END'],
                'unexpected patch operations')
        result[f'{crc:04x}'] = {'slave_hunk_offset': f'{target:04x}', 'entries': entries,
                               'enhancement_input_verified': crc == 0x00e8}
    return result


def assembly(code):
    md = capstone.Cs(capstone.CS_ARCH_M68K, capstone.CS_MODE_M68K_000)
    decoded = {}
    for start, end in CODE:
        pos = start
        while pos < end:
            insn = next(md.disasm(code[pos:end], pos, count=1), None)
            require(insn is not None and insn.mnemonic != 'dc.w' and
                    insn.size > 0 and pos + insn.size <= end, f'undecodable instruction at {pos:x}')
            mnemonic, operands = insn.mnemonic, insn.op_str
            if mnemonic.split('.')[0] in ('btst', 'bset', 'bclr', 'bchg'):
                mnemonic = mnemonic.split('.')[0]
            # Capstone reports MOVEM PC targets two bytes short (mask extension).
            if mnemonic.startswith('movem'):
                operands = re.sub(r'\$([0-9a-f]+)(?=\(pc)',
                                  lambda m: '$%x' % (int(m[1], 16) + 2), operands)
            operands = re.sub(r'\$([0-9a-f]+)(?=\(pc|, pc)', r'slave+$\1', operands)
            if mnemonic.startswith('b') and mnemonic.split('.')[0] not in ('btst', 'bset', 'bclr', 'bchg'):
                operands = re.sub(r'^\$([0-9a-f]+)$', r'slave+$\1', operands)
            if mnemonic.startswith('db'):
                operands = re.sub(r'\$([0-9a-f]+)$', r'slave+$\1', operands)
            operands = re.sub(r'\$([0-9a-f]+)\.(w|l)',
                              lambda m: '(' + str(int(m[1], 16) -
                              (65536 if m[2] == 'w' and int(m[1], 16) >= 32768 else 0)) + ').' + m[2], operands)
            if mnemonic == 'moveq':
                operands = re.sub(r'#\$([0-9a-f]+)',
                                  lambda m: '#' + str((int(m[1], 16) + 128) % 256 - 128), operands)
            decoded[pos] = (insn.size, mnemonic + ' ' + operands)
            pos += insn.size
    patches = {}
    for _, _, target in SELECTORS:
        body = ['\tPL_START']
        for offset, command, argument in decode(code, target):
            if command == 'END':
                body.append('\tPL_END')
            else:
                value = ('slave+$' + argument.split(':')[1] if argument.startswith('slave:')
                         else '$' + argument.removeprefix('0x'))
                body.append(f'\tPL_{command} ${offset:x},{value}')
        patches[target] = '\n'.join(body)
    lines = ['; Derived from pinned original. Keep in ignored tmp/.',
             '\tinclude "whdload.i"', '\torg 0', 'slave:']
    pos = 0
    while pos < len(code):
        lines += [f'\tifne *-slave-${pos:x}', '\tfail "offset drift"', '\tendif', f'OS_{pos:04x}:']
        if pos in patches:
            size = 0x46
            lines.append(patches[pos])
        elif pos in decoded:
            size, text = decoded[pos]
            lines.append('\t' + text)
        else:
            size = min(16, len(code) - pos)
            while any(pos < address < pos + size for address in (*decoded, *patches)):
                size -= 1
            lines.append('\tdc.b ' + ','.join(f'${byte:02x}' for byte in code[pos:pos + size]))
        pos += size
    return '\n'.join(lines) + '\n', len(decoded)


def build(out, original, game):
    out = new_output(out)
    require(sha(original) == SLAVE_SHA, 'unsupported/changed OCS slave; nothing overwritten')
    sites = guard_game(game)
    code = original[0x20:-4]
    require(len(code) == 0x14a8, 'unexpected slave hunk length')
    revisions = revision_lists(code)
    source, count = assembly(code)
    out.mkdir(parents=True)
    (out / 'WingCommanderOCS.s').write_text(source)
    subprocess.run([os.environ['VASM'], '-m68000', '-spaces', '-no-opt', '-Fbin',
                    '-I' + str(Path(os.environ['WHDLOAD']) / 'Include'), '-I' + os.environ['NDK'],
                    '-L', str(out / 'slave.lst'), '-o', str(out / 'payload.bin'),
                    str(out / 'WingCommanderOCS.s')], check=True)
    payload = (out / 'payload.bin').read_bytes()
    require(payload == code, 'reassembled payload differs from original')
    result = struct.pack('>8I', 0x3f3, 0, 1, 0, 0, len(payload)//4,
                         0x3e9, len(payload)//4) + payload + struct.pack('>I', 0x3f2)
    require(result == original, 'reconstructed HUNK differs from original')
    (out / 'WingCommander.Slave').write_bytes(result)
    report = {'variant': 'ocs', 'bytes': len(result), 'sha256': sha(result), 'byte_identical': True,
              'assembled_instructions': count, 'game_sha256': sha(game),
              'revisions': revisions, 'displaced_sites': sites,
              'runtime_hooks_added': False, 'boot_validated': False}
    (out / 'report.json').write_text(json.dumps(report, indent=2) + '\n')
    return report


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', required=True)
    parser.add_argument('--input', default=VARIANT.SLAVE)
    parser.add_argument('--game', default=VARIANT.GAME)
    args = parser.parse_args(argv)
    out = new_output(args.output)
    report = build(out, (ROOT / args.input).read_bytes(), (ROOT / args.game).read_bytes())
    print(json.dumps({k: report[k] for k in ('bytes', 'sha256', 'byte_identical', 'assembled_instructions')}))


if __name__ == '__main__':
    try:
        main()
    except (ValueError, OSError, KeyError, subprocess.CalledProcessError) as error:
        sys.exit(str(error))
